package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.ClientUriVO;

class ClientUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of client uri of oauth client")
  void test_client_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    ClientUriValueHolder<Object> value = new ClientUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.clientUri("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getClientUriValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getClientUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.clientUriNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getClientUriValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getClientUri().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of client uri of oauth client")
  void test_client_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    ClientUriValueHolder<Object> value = new ClientUriValueHolder<>(holder);
    ClientUriVO vo = ClientUriVO.from("one");
    Assertions.assertFalse(value.getClientUriValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.clientUri(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getClientUriValue().orElseThrow());
    Assertions.assertSame(holder, value.clientUri(Optional.empty()));
    Assertions.assertFalse(value.getClientUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.clientUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getClientUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of client uri of oauth client against the original")
  void test_client_uri_value_holder_read() {
    Object holder = new Object();
    ClientUriValueHolder<Object> value = new ClientUriValueHolder<>(holder);
    ClientUriVO vo = ClientUriVO.from("one");
    ClientUriVO other = ClientUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getClientUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readClientUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readClientUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.clientUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readClientUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readClientUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of client uri of oauth client")
  void test_client_uri_value_holder_unset() {
    Object holder = new Object();
    ClientUriValueHolder<Object> value = new ClientUriValueHolder<>(holder);
    ClientUriVO vo = ClientUriVO.from("one");
    value.clientUri(vo);
    Assertions.assertSame(holder, value.unsetClientUriIfMatches("clientUri_other"));
    Assertions.assertTrue(value.getClientUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetClientUriIfMatches("clientUri"));
    Assertions.assertFalse(value.getClientUriValue().isPresent(),
        "The field name must clear the value");
    value.clientUri(vo);
    Assertions.assertSame(holder, value.unsetClientUri());
    Assertions.assertFalse(value.getClientUriValue().isPresent(), "Unset must clear the value");
  }
}
